esbmc_test_source:
contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(address caller) public payable {
        require(true);

        // record balance of c before the call
        uint256 beforeBalance = address(c).balance;

        // Attempt to call sudicideAnyone from this contract (which is NOT the original deployer/owner of C)
        // Since the checker deploys a fresh C and sets InvMutTest as msg.sender when interacting,
        // InvMutTest is not the owner (owner was the deployer of C), so call should revert.
        bool reverted;
        c.sudicideAnyone(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // After attempted call, balance must be unchanged if call reverted; if it did not revert,
        // then it implies InvMutTest was owner and selfdestruct executed, making c balance zero.
        // General invariant: either call reverted and balance unchanged, or call succeeded and balance is zero.
        assert(reverted ? address(c).balance == beforeBalance : address(c).balance == 0);
    }

    // accept ether if selfdestruct sends any to this contract in successful case
    receive() external payable {}
}

